∀ {m n : ℕ} {P : ProbabilityTheory.Copula.IntervalPartition m} {Q : ProbabilityTheory.Copula.IntervalPartition n}
  (A : ProbabilityTheory.Copula.CellMass P Q) (u v : ↑unitInterval),
  A.checkMin.cdf ![u, v] = ∑ i, ∑ j, A.mass i j * Min.min ↑(P.coord i u) ↑(Q.coord j v)

∀ {m n : ℕ} {P : ProbabilityTheory.Copula.IntervalPartition m} {Q : ProbabilityTheory.Copula.IntervalPartition n}
  (A : ProbabilityTheory.Copula.CellMass P Q),
  A.checkMin.kendallTau = A.checkerboard.kendallTau + ((Matrix.of A.mass).transpose * Matrix.of A.mass).trace

∀ {m n : ℕ} {P : ProbabilityTheory.Copula.IntervalPartition m} {Q : ProbabilityTheory.Copula.IntervalPartition n}
  (A : ProbabilityTheory.Copula.CellMass P Q) (u v : ↑unitInterval),
  A.checkW.cdf ![u, v] = ∑ i, ∑ j, A.mass i j * Max.max (↑(P.coord i u) + ↑(Q.coord j v) - 1) 0

∀ {m n : ℕ} {P : ProbabilityTheory.Copula.IntervalPartition m} {Q : ProbabilityTheory.Copula.IntervalPartition n}
  (A : ProbabilityTheory.Copula.CellMass P Q),
  A.checkW.kendallTau = A.checkerboard.kendallTau - ((Matrix.of A.mass).transpose * Matrix.of A.mass).trace

∀ {m n : ℕ} {P : ProbabilityTheory.Copula.IntervalPartition m} {Q : ProbabilityTheory.Copula.IntervalPartition n}
  (A : ProbabilityTheory.Copula.CellMass P Q) (u v : ↑unitInterval),
  A.checkerboard.cdf ![u, v] = ∑ i, ∑ j, A.mass i j * ↑(P.coord i u) * ↑(Q.coord j v)
